package main

import (
	"context"
	"sync"

	"github.com/mellifera/mellifera/internal/scan"
)

// scanRun is one library scan's in-flight record: its completion channel plus
// the (result, err) the run recorded. close(done) is the publication point —
// the outcome fields are written before it, so a joiner reading them after a
// receive from done sees the final values without further locking (watch-scan
// D4).
type scanRun struct {
	done   chan struct{}
	result scan.Result
	err    error
}

// scanFlight is the per-library scan single-flight (watch-scan D4): at most
// one scan per library at a time, no matter which trigger source fires. The
// manual POST (api.Deps.Scan) and the watcher (watch.Deps.Scan) route through
// the SAME instance, so the two join instead of stampeding the store — one
// seam, both directions join. DISTINCT libraries never share state: the map
// is keyed per library and fn executes outside the lock, so independent
// libraries scan concurrently.
//
// Context discipline: a run executes under its STARTER's context. The
// watcher's triggers use the process ctx, so an HTTP client disconnect can
// never kill a watcher-started run; a joiner's own ctx governs ONLY its wait —
// a disconnecting joiner abandons the wait (returns ctx.Err()) while the run
// continues and records its outcome for the next joiner. Both trigger paths
// reach run through dispatched goroutines (the D3 dispatch law), so a waiting
// joiner never blocks event ingestion or the next reconcile tick.
type scanFlight struct {
	mu   sync.Mutex
	runs map[int64]*scanRun
}

// newScanFlight returns an empty single-flight.
func newScanFlight() *scanFlight {
	return &scanFlight{runs: make(map[int64]*scanRun)}
}

// run scans libraryID through fn, joining an in-flight run for the same
// library or starting a new one. fn's signature mirrors api.Deps.Scan
// (router.go's Deps.Scan func-field) so main.go re-routes both trigger
// closures through this one seam unchanged.
//
// A trigger that finds a run in flight waits on it and receives the running
// run's recorded outcome; otherwise it starts the run under ITS OWN ctx and
// records (result, err) for joiners. The recorded run is removed from the map
// only after its outcome is published (close(done)), so a trigger landing in
// the completion window still joins the recorded outcome instead of racing
// into a second fn execution; after removal, the next trigger starts a fresh
// run — a completed scan is never replayed indefinitely.
func (f *scanFlight) run(ctx context.Context, libraryID int64, fn func(context.Context, int64) (scan.Result, error)) (scan.Result, error) {
	f.mu.Lock()
	if existing, ok := f.runs[libraryID]; ok {
		f.mu.Unlock()
		select {
		case <-existing.done:
			return existing.result, existing.err
		case <-ctx.Done():
			// The waiter's disconnect abandons only the WAIT — the run keeps
			// going under its starter's ctx and records its outcome for the
			// next joiner.
			return scan.Result{}, ctx.Err()
		}
	}
	current := &scanRun{done: make(chan struct{})}
	f.runs[libraryID] = current
	f.mu.Unlock()

	// Starter's path: execute under the STARTER's ctx (outside the lock, so
	// other libraries scan concurrently), then publish the outcome.
	current.result, current.err = fn(ctx, libraryID)
	close(current.done)

	f.mu.Lock()
	delete(f.runs, libraryID)
	f.mu.Unlock()

	return current.result, current.err
}
